// Extract structured data from alert email
const email = $input.first().json;

const subject = email.subject || '';
const body = email.bodyPreview || email.body?.content || '';
const sender = email.from?.emailAddress?.address || '';
const receivedAt = email.receivedDateTime || new Date().toISOString();

// Common alert patterns — extend these regexes for your specific services
const patterns = {
  // Device/hostname patterns
  device: [
    /(?:device|host|server|computer|endpoint|machine)[:\s]+([\w\-\.]+)/i,
    /([\w\-]+(?:\.local|\.[a-z]{2,})?)[\s]+(?:is|has|alert|down|offline|failed)/i,
    /(?:alert on|triggered on|from)[:\s]+([\w\-\.]+)/i,
    /hostname[:\s]+([\w\-\.]+)/i
  ],
  // Company/client patterns
  company: [
    /(?:client|customer|company|tenant|account)[:\s]+([\w\s\-\.&,]+?)(?:\s*[-|]|\n|$)/i,
    /\[([\w\s\-\.&]+)\]/,
    /^([\w\s\-\.&]+?)[:\s]+(?:alert|warning|critical|offline|down)/i
  ],
  // Alert type/severity
  severity: [
    /(?:severity|priority|level)[:\s]+(critical|high|medium|low|warning|info)/i,
    /\b(critical|urgent|high|medium|low|warning|info)\b/i
  ],
  // Alert description
  alertType: [
    /(?:alert|event)[:\s]+([^\n]+)/i,
    /(?:status|condition)[:\s]+([^\n]+)/i
  ]
};

function extractFirst(text, regexList) {
  for (const regex of regexList) {
    const match = (subject + ' ' + text).match(regex);
    if (match && match[1]) return match[1].trim();
  }
  return null;
}

const device = extractFirst(body, patterns.device);
const company = extractFirst(body, patterns.company);
const severity = extractFirst(body, patterns.severity) || 'Medium';
const alertType = extractFirst(body, patterns.alertType) || subject;

return [{
  json: {
    subject,
    body,
    sender,
    receivedAt,
    parsed: {
      device: device || '',
      company: company || '',
      severity: severity,
      alertType: alertType,
      needsAIAssist: !device || !company
    },
    raw: email
  }
}];

