const emailData = $('Parse Alert from Email').first().json;
const aiRaw = $input.first().json;

// Parse AI JSON response
let aiData = {};
try {
  const content = aiRaw.choices?.[0]?.message?.content || '{}';
  aiData = JSON.parse(content.replace(/```json|```/g, '').trim());
} catch(e) {
  aiData = {};
}

// Prefer AI extraction, fall back to regex
const company = aiData.company || emailData.parsed.company || '';
const device = aiData.device || emailData.parsed.device || '';
const severity = aiData.severity || emailData.parsed.severity || 'Medium';
const alertSummary = aiData.alert_summary || emailData.parsed.alertType || emailData.subject;
const serviceSource = aiData.service_source || 'Unknown Service';

const severityMap = { Critical: 1, High: 2, Medium: 3, Low: 4 };
const priorityId = severityMap[severity] || 3;

return [{
  json: {
    company,
    device,
    severity,
    priorityId,
    alertSummary,
    serviceSource,
    subject: emailData.subject,
    body: emailData.body,
    receivedAt: emailData.receivedAt,
    sender: emailData.sender
  }
}];

const parsed = $('Merge Parsed Data').first().json;
const clientResp = $('Halo PSA - Find Client').first().json;
const assetResp = $('Halo PSA - Find Asset/Device').first().json;

// Halo returns { clients: [...] } or { assets: [...] }
const clients = clientResp.clients || clientResp || [];
const assets = assetResp.assets || assetResp || [];

const clientArr = Array.isArray(clients) ? clients : [];
const assetArr = Array.isArray(assets) ? assets : [];

const client = clientArr[0] || null;
const asset = assetArr[0] || null;

return [{
  json: {
    ...parsed,
    clientId: client?.id || null,
    clientName: client?.name || parsed.company || 'Unknown Client',
    siteId: client?.main_site_id || null,
    assetId: asset?.id || null,
    assetName: asset?.inventory_number || asset?.name || parsed.device || 'Unknown Device',
    clientFound: !!client,
    assetFound: !!asset
  }
}];
